chartjs.data:
model -> {
	period = ifElse(isEmpty($model),
		new(`tl.ai.monitor:Period`, transient: true)
			..set(`tl.ai.monitor:Period#preset`, 30),
		$model);
	executions = all(`tl.ai.execution:AgentExecution`);
	startedAt = e -> $e.get(`tl.ai.execution:AgentExecution#startedAt`);
	start = $period.get(`tl.ai.monitor:Period#windowStart`);
	end = $period.get(`tl.ai.monitor:Period#windowEnd`);
	// "Alle" drops the filter rather than widening it: an unfiltered pass over the table is
	// measurably cheaper than one that tests a date on every row.
	recent = ifElse(isEmpty($start) && isEmpty($end), $executions,
		$executions.filter(e -> (isEmpty($start) || $startedAt($e) >= $start)
			&& (isEmpty($end) || $startedAt($e) < $end)));
	byAgent = $recent.groupBy(e -> $e.get(`tl.ai.execution:AgentExecution#agentName`));
	ranked = $byAgent.keySet().toList().sort(desc(comparator(n -> $byAgent[$n].size())));
	names = ifElse($ranked.size() > 10, $ranked.subList(0, 10), $ranked);
	{
		'type': 'bar',
		'data': {
			'labels': $names,
			'datasets': list({
				'label': #('Runs'@en, 'Läufe'@de).localize(),
				'data': $names.map(n -> $byAgent[$n].size()),
				'backgroundColor': '#2968c8',
				'maxBarThickness': 26
			})
		},
		'options': {
			'indexAxis': 'y',
			'maintainAspectRatio': false,
			'plugins': {
				'legend': { 'display': false },
				// An empty plot area reads as "nothing happened here" whatever the reason
				// was, so a period that selects no run has to say which reason it is. A
				// range that lies wholly in the future is the case a reader is most likely
				// to have produced by a typo in a year.
				'title': {
					'display': isEmpty($recent),
					'text': ifElse(!isEmpty($start) && $start > now(),
						#('The selected period lies in the future.'@en,
							'Der gewählte Zeitraum liegt in der Zukunft.'@de).localize(),
						#('No runs in the selected period.'@en,
							'Keine Läufe im gewählten Zeitraum.'@de).localize()),
					'color': '#8a8a8a'
				}
			},
			'scales': { 'x': { 'beginAtZero': true } }
		}
	};
}
